[{"order":1,"type":"heading","text":"Authentication, Permissions, and Throttling in DRF"},{"order":2,"type":"paragraph","text":"Building robust web APIs requires securing endpoints, ensuring users have the right access levels, and protecting servers from abuse. Django Rest Framework (DRF) provides built-in, highly customizable mechanisms for Authentication, Permissions, and Throttling."},{"order":3,"type":"subheading","text":"1. Authentication in DRF"},{"order":4,"type":"paragraph","text":"Authentication is the mechanism of associating an incoming request with a set of credentials, such as the user making the request or the token they provided. DRF executes authentication classes sequentially before checking permissions."},{"order":5,"type":"code","text":"REST_FRAMEWORK = {
    "DEFAULT_AUTHENTICATION_CLASSES": [
        "rest_framework.authentication.SessionAuthentication",
        "rest_framework.authentication.TokenAuthentication"
    ]
}"},{"order":6,"type":"subheading","text":"2. Permissions in DRF"},{"order":7,"type":"paragraph","text":"Permissions determine whether a request should be granted or denied access based on the authenticated user. DRF provides several permission classes out of the box, such as IsAuthenticated, IsAdminUser, and AllowAny."},{"order":8,"type":"code","text":"from rest_framework.permissions import IsAuthenticated
from rest_framework.views import APIView
from rest_framework.response import Response

class SecureDataView(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request):
        content = {"message": "This is protected data."}
        return Response(content)"},{"order":9,"type":"subheading","text":"3. Throttling in DRF"},{"order":10,"type":"paragraph","text":"Throttling limits the rate of requests that a client can make to an API. This helps prevent scraping, DDoS attacks, and resource exhaustion. DRF supports user-based, IP-based, and anonymous rate limiting."},{"order":11,"type":"code","text":"REST_FRAMEWORK = {
    "DEFAULT_THROTTLE_CLASSES": [
        "rest_framework.throttling.AnonRateThrottle",
        "rest_framework.throttling.UserRateThrottle"
    ],
    "DEFAULT_THROTTLE_RATES": {
        "anon": "100/day",
        "user": "1000/day"
    }
}"},{"order":12,"type":"bullet_point","text":"SessionAuthentication is typically used for browser-based APIs interacting with Django's session backend."},{"order":13,"type":"bullet_point","text":"TokenAuthentication is ideal for client-server architectures like mobile applications and single-page apps."},{"order":14,"type":"bullet_point","text":"Custom permissions can be built by inheriting from BasePermission and overriding the has_permission method."}]
